mapper.select:
SELECT *
FROM shopwizard.tOrdOrderSoclQuot

    AND ChnlName = #{pChnlName}
    AND DealName LIKE CONCAT('%',#{pDealName},'%')
    AND MatchProdCode LIKE CONCAT('%',#{pMatchProdCode},'%')
    AND ShopCode LIKE CONCAT('%',#{pShopCode},'%')
    AND ProdCode = #{pProdCode}
    AND ProdName LIKE CONCAT('%',#{pProdName},'%')
    AND DealNo = #{pDealNo}


    ORDER BY ${sidx} ${sord}
    ORDER BY ChnlName, DealName, MatchProdCode

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderSoclQuot

    AND ChnlName = #{pChnlName}
    AND DealName = #{pDealName}
    AND MatchProdCode = #{pMatchProdCode}
    AND ProdCode = #{pProdCode}
    AND ProdName LIKE CONCAT('%',#{pProdName},'%')
    AND DealNo = #{pDealNo}
